window.FLOW_SNIPPETS = {"at_init":{"file":"backend/elm327_bt.py","language":"python","name":"AT_INIT_SEQUENCE","start":69,"end":75,"lines":["AT_INIT_SEQUENCE = [","    (b\"ATZ\\r\",    False),   # reset -- always required","    (b\"ATE0\\r\",   False),   # echo off -- required for clean parsing","    (b\"ATL0\\r\",   False),   # linefeeds off -- cleaner responses","    (b\"ATSP0\\r\",  False),   # auto-detect OBD protocol (CAN/KWP etc.)","    (b\"ATH0\\r\",   True),    # hide CAN headers -- fake chips may reject this","]"],"highlight":{"all":[70,71,73]}},"initialise_elm327":{"file":"backend/elm327_bt.py","language":"python","name":"initialise_elm327","start":154,"end":185,"lines":["def initialise_elm327(ser: serial.Serial) -> bool:","    \"\"\"","    Send the AT init sequence to the ELM327 with warm-up (Change 4).","    Returns True if essential commands succeeded, False if adapter is unusable.","    \"\"\"","    print(\"[BT] Initialising ELM327...\")","    time.sleep(1.5)   # Change 4: Bluetooth warm-up pause (raise from 0.5s to 1.5s)","","    # Change 4: Send throwaway ATZ to clean dirty initial BT link","    try:","        ser.reset_input_buffer()","        ser.write(b\"ATZ\\r\")","        time.sleep(1.0)","        ser.reset_input_buffer()","    except Exception:","        pass","","    for cmd, skip_if_unknown in AT_INIT_SEQUENCE:","        resp = send_at(ser, cmd, skip_if_unknown=skip_if_unknown)","        # If write failed or timed out completely on essential commands, abort","        if not resp and not skip_if_unknown:","            print(f\"[BT] Init failed (no response/timeout on {cmd.decode().strip()}) -- check if adapter is powered.\")","            return False","        if cmd == b\"ATZ\\r\":","            time.sleep(1.5)   # chip needs time to reset","            continue","        if \"?\" in resp and not skip_if_unknown:","            print(f\"[BT] Init failed on {cmd.decode().strip()} -- aborting.\")","            return False","","    print(\"[BT] ELM327 initialised successfully.\")","    return True"],"highlight":{"all":[171,172]}},"query_pid":{"file":"backend/elm327_bt.py","language":"python","name":"query_pid","start":188,"end":220,"lines":["def query_pid(ser: serial.Serial, pid: int, fast: bool = False, is_first: bool = False) -> str:","    \"\"\"","    Send a Mode 01 PID request and return the cleaned OBD response string.","    Implements Change 2 (SEARCHING prefix recovery) and Change 5/6 (timeout & fast mode).","    \"\"\"","    try:","        ser.reset_input_buffer()","        # Change 6: Optional faster polling suffix (\"1\")","        cmd_str = f\"01 {pid:02X} 1\\r\" if fast else f\"01 {pid:02X}\\r\"","        ser.write(cmd_str.encode())","    except (serial.SerialTimeoutException, serial.SerialException) as e:","        print(f\"[BT] ERROR: Write failed for PID {hex(pid)} ({e}) -- check BT link.\")","        return f\"7F 01 {pid:02X}\"","","    # Change 5: 5s timeout on very first request (where SEARCHING occurs), 2s otherwise","    timeout = 5.0 if is_first else READ_TIMEOUT","    response = read_until_prompt(ser, timeout=timeout).strip().upper()","","    if not response:","        return f\"7F 01 {pid:02X}\"","","    # Change 2: Recover data after SEARCHING... prefix and verify requested PID","    response = \" \".join(response.split())","    idx = response.find(\"41 \")","    if idx == -1:","        return f\"7F 01 {pid:02X}\"   # no usable Mode 01 data -> null","","    response = response[idx:]","    tokens = response.split()","    if len(tokens) < 2 or tokens[1] != f\"{pid:02X}\":","        return f\"7F 01 {pid:02X}\"   # echoed PID mismatch -> null","","    return response"],"highlight":{"all":[196,197,204,211,213]}},"decode_pid":{"file":"backend/obd_decoder.py","language":"python","name":"decode_pid","start":160,"end":192,"lines":["def decode_pid(hex_str: str):","    \"\"\"","    Decode a raw ELM327 reply into a value.","","    Returns the decoded value, or None if the reply is a negative response,","    malformed, empty, or for a PID we do not handle.","","      decode_pid(\"41 0C 0B 34\") -> 717.0","      decode_pid(\"7F 01 2F\")    -> None","    \"\"\"","    if not hex_str or not hex_str.strip():","        return None","","    tokens = hex_str.strip().upper().split()","    if tokens[0] == \"7F\":","        return None","    if len(tokens) < 2 or tokens[0] != \"41\":","        return None","","    try:","        pid = int(tokens[1], 16)","        data = [int(b, 16) for b in tokens[2:]]","    except ValueError:","        return None","","    decoder = _PID_DECODERS.get(pid)","    if decoder is None:","        return None","","    try:","        return decoder(data)","    except (IndexError, ZeroDivisionError):","        return None"],"highlight":{"all":[173,174,180,181,185,190]}},"d_0x0C":{"file":"backend/obd_decoder.py","language":"python","name":"_d_0x0C","start":131,"end":131,"lines":["def _d_0x0C(d): return ((d[0] * 256) + d[1]) / 4.0        # RPM"],"highlight":{"all":[131]}},"d_0x0D":{"file":"backend/obd_decoder.py","language":"python","name":"_d_0x0D","start":132,"end":132,"lines":["def _d_0x0D(d): return d[0]                                # speed km/h"],"highlight":{"all":[132]}},"d_0x05":{"file":"backend/obd_decoder.py","language":"python","name":"_d_0x05","start":133,"end":133,"lines":["def _d_0x05(d): return d[0] - 40                           # coolant C"],"highlight":{"all":[133]}},"d_0x11":{"file":"backend/obd_decoder.py","language":"python","name":"_d_0x11","start":135,"end":135,"lines":["def _d_0x11(d): return round(d[0] * 100 / 255, 1)          # throttle %"],"highlight":{"all":[135]}},"d_0x2F":{"file":"backend/obd_decoder.py","language":"python","name":"_d_0x2F","start":136,"end":136,"lines":["def _d_0x2F(d): return round(d[0] * 100 / 255, 1)          # fuel level %"],"highlight":{"all":[136]}},"pack_packet":{"file":"backend/obd_decoder.py","language":"python","name":"pack_packet","start":255,"end":336,"lines":["def pack_packet(decoded: dict, gps: dict = None, extras: dict = None) -> bytes:","    \"\"\"","    Pack decoded values into the 32-byte packet.","","    Args:","      decoded: {pid_int: value_or_None}. Keys per TARGET_PIDS.","               0x01 may be a (mil_on, dtc_count) tuple or None.","      gps:     {lat, lng, sats, fix} or None. lat/lng None -> sentinel.","      extras:  optional dict:","                 battery_v : float from ATRV, or None","                 gear      : int 0-6 / 0x0E reverse, or None -> unknown","                 seq       : int sequence counter","                 can       : {\"brake\": bool|None, \"clutch\": bool|None,","                              \"ac\": bool|None}   None = not found yet","                 health    : {\"power_ok\": bool, \"gps_ok\": bool, \"can_ok\": bool}","","    Returns 32 bytes, CRC-8 in byte 31.","    \"\"\"","    gps = gps or {}","    extras = extras or {}","","    # -- GPS -------------------------------------------------------------","    lat_raw = _coord(gps.get(\"lat\"))","    lng_raw = _coord(gps.get(\"lng\"))","    sats = min(int(gps.get(\"sats\") or 0), 63)","    fix = bool(gps.get(\"fix\"))","    sats_fix = (sats & 0x3F) | (0x40 if fix else 0x00)","","    # -- MIL / DTC (PID 0x01) --------------------------------------------","    mil_dtc = decoded.get(0x01)","    if mil_dtc is None:","        mil_dtc_raw = U8_NA","    else:","        mil_on, dtc_count = mil_dtc","        mil_dtc_raw = (0x80 if mil_on else 0x00) | (min(dtc_count, 127) & 0x7F)","","    # -- Byte 24: AC / brake / clutch with validity bits ------------------","    can = extras.get(\"can\") or {}","    flags = 0","    for state_bit, valid_bit, key in ((0, 1, \"brake\"), (2, 3, \"clutch\"), (4, 5, \"ac\")):","        v = can.get(key)","        if v is not None:                      # we found this signal","            flags |= (1 << valid_bit)","            if v:","                flags |= (1 << state_bit)","","    # -- Byte 29: device health ------------------------------------------","    h = extras.get(\"health\") or {}","    health = 0","    if h.get(\"power_ok\"): health |= 0x80","    if h.get(\"gps_ok\"):   health |= 0x40","    if h.get(\"can_ok\"):   health |= 0x20","","    body = struct.pack(","        _STRUCT,","        int(time.time()) & 0xFFFFFFFF,          # 0-3   timestamp","        _u16(decoded.get(0x0C), 4),             # 4-5   RPM","        _u8(decoded.get(0x0D)),                 # 6     speed","        lat_raw,                                # 7-10  lat","        lng_raw,                                # 11-14 lng","        sats_fix,                               # 15    sats+fix","        _u16(decoded.get(0x10), 100),           # 16-17 MAF","        _u8(extras.get(\"gear\"), 0, 254),        # 18    gear","        _pct(decoded.get(0x11)),                # 19    throttle","        _temp(decoded.get(0x05)),               # 20    coolant","        _pct(decoded.get(0x2F)),                # 21    fuel","        _u8(extras.get(\"battery_v\") * 10        # 22    battery","            if extras.get(\"battery_v\") is not None else None),","        mil_dtc_raw,                            # 23    MIL+DTC","        flags,                                  # 24    AC/brake/clutch","        _pct(decoded.get(0x04)),                # 25    engine load","        _temp(decoded.get(0x0F)),               # 26    intake","        _temp(decoded.get(0x46)),               # 27    ambient","        _u8(decoded.get(0x0B)),                 # 28    MAP","        health,                                 # 29    device health","        int(extras.get(\"seq\", 0)) & 0xFF,       # 30    sequence","    )","","    assert len(body) == 31, f\"body is {len(body)} bytes, expected 31\"","    packet = body + bytes([crc8(body)])","    assert len(packet) == 32","    return packet"],"highlight":{"all":[308,334],"0x0C":[311],"0x0D":[312],"0x05":[319],"0x11":[318],"0x2F":[320]}},"crc8":{"file":"backend/obd_decoder.py","language":"python","name":"crc8","start":213,"end":219,"lines":["def crc8(data: bytes) -> int:","    crc = 0x00","    for byte in data:","        crc ^= byte","        for _ in range(8):","            crc = ((crc << 1) ^ 0x07) & 0xFF if (crc & 0x80) else (crc << 1) & 0xFF","    return crc"],"highlight":{"all":[216,218]}},"coord":{"file":"backend/obd_decoder.py","language":"python","name":"_coord","start":248,"end":252,"lines":["def _coord(val):","    \"\"\"int32 degrees*1e6. None -> 0x7FFFFFFF.\"\"\"","    if val is None:","        return I32_NA","    return int(round(val * 1_000_000))"],"highlight":{"all":[252]}},"unpack_packet":{"file":"backend/obd_decoder.py","language":"python","name":"unpack_packet","start":348,"end":409,"lines":["def unpack_packet(raw_bytes: bytes) -> dict:","    \"\"\"","    Unpack 32 bytes back to a JSON-ready dict.","    Sentinels become None. Validates the CRC-8.","    \"\"\"","    if len(raw_bytes) != 32:","        raise ValueError(f\"Expected 32 bytes, got {len(raw_bytes)}\")","","    crc_valid = crc8(raw_bytes[:31]) == raw_bytes[31]","    f = struct.unpack(_STRUCT, raw_bytes[:31])","","    (ts, rpm_r, spd_r, lat_r, lng_r, satsfix, maf_r, gear_r, thr_r,","     cool_r, fuel_r, batt_r, mildtc_r, flags, load_r, intake_r,","     amb_r, map_r, health, seq) = f","","    # MIL / DTC","    if mildtc_r == U8_NA:","        mil_on, dtc_count = None, None","    else:","        mil_on = bool(mildtc_r & 0x80)","        dtc_count = mildtc_r & 0x7F","","    # Byte 24: state only meaningful if the matching valid bit is set","    def _flag(state_bit, valid_bit):","        return bool(flags & (1 << state_bit)) if (flags & (1 << valid_bit)) else None","","    return {","        \"schema_version\": SCHEMA_VERSION,","        \"ts\": ts * 1000,","        \"vehicle\": {","            \"rpm\":              _r_u16(rpm_r, 4),","            \"speed_kmh\":        _r_u8(spd_r),","            \"gear\":             None if gear_r == U8_NA else gear_r,","            \"throttle_pct\":     _r_pct(thr_r),","            \"coolant_c\":        _r_temp(cool_r),","            \"fuel_level_pct\":   _r_pct(fuel_r),","            \"maf_gps\":          _r_u16(maf_r, 100),","            \"engine_load_pct\":  _r_pct(load_r),","            \"intake_temp_c\":    _r_temp(intake_r),","            \"ambient_temp_c\":   _r_temp(amb_r),","            \"map_kpa\":          _r_u8(map_r),","            \"battery_v\":        None if batt_r == U8_NA else round(batt_r / 10.0, 1),","            \"mil_on\":           mil_on,","            \"dtc_count\":        dtc_count,","            \"brake\":            _flag(0, 1),","            \"clutch\":           _flag(2, 3),","            \"ac_on\":            _flag(4, 5),","        },","        \"gps\": {","            \"lat\":  _r_coord(lat_r),","            \"lng\":  _r_coord(lng_r),","            \"sats\": satsfix & 0x3F,","            \"fix\":  bool(satsfix & 0x40),","        },","        \"device\": {","            \"power_ok\": bool(health & 0x80),","            \"gps_ok\":   bool(health & 0x40),","            \"can_ok\":   bool(health & 0x20),","            \"seq\":      seq,","        },","        \"crc_valid\": crc_valid,","    }"],"highlight":{"all":[356,357],"0x0C":[378],"0x0D":[379],"0x05":[382],"0x11":[381],"0x2F":[383]}},"parse_nmea_lat_lng":{"file":"sensing/gps_neo6m_pi.py","language":"python","name":"parse_nmea_lat_lng","start":66,"end":106,"lines":["def parse_nmea_lat_lng(coord_str: str, direction: str) -> Optional[float]:","    \"\"\"","    Convert NMEA degree-minute coordinate format to Decimal Degrees.","    ","    Format:","      Latitude:  DDMM.MMMM (e.g., '1255.2218', 'N') -> 12 + 55.2218/60 = 12.920363","      Longitude: DDDMM.MMMM (e.g., '08007.8998', 'E') -> 80 + 07.8998/60 = 80.131663","      ","    Args:","        coord_str: The raw NMEA coordinate string from the sentence.","        direction: 'N', 'S', 'E', or 'W'.","        ","    Returns:","        Decimal degree float (negative for S/W), or None if parsing fails.","    \"\"\"","    if not coord_str or not direction or len(coord_str) < 4:","        return None","    try:","        # Latitude has 2 degree digits before MM.MMMM; Longitude has 3 degree digits","        if direction in ('N', 'S'):","            deg_len = 2","        elif direction in ('E', 'W'):","            deg_len = 3","        else:","            return None","","        # Handle potential zero-padding issues gracefully","        if len(coord_str.split('.')[0]) <= deg_len:","            # Fallback split if standard formatting slightly deviates","            deg_len = len(coord_str.split('.')[0]) - 2","","        degrees = float(coord_str[:deg_len])","        minutes = float(coord_str[deg_len:])","        decimal_degrees = degrees + (minutes / 60.0)","","        if direction in ('S', 'W'):","            decimal_degrees = -decimal_degrees","","        return round(decimal_degrees, 6)","    except (ValueError, IndexError):","        return None"],"highlight":{"all":[97,98,99]}},"parse_gga":{"file":"sensing/gps_neo6m_pi.py","language":"python","name":"NMEAParser._parse_gga","start":208,"end":256,"lines":["    def _parse_gga(self, fields: list):","        \"\"\"Parse $GPGGA (Global Positioning System Fix Data)\"\"\"","        # [0]=$GPGGA, [1]=UTC Time, [2]=Lat, [3]=N/S, [4]=Lng, [5]=E/W, [6]=Fix quality, [7]=Sat count, [8]=HDOP, [9]=Altitude, ...","        if len(fields) < 10:","            return","","        # UTC Time","        if fields[1] and len(fields[1]) >= 6:","            t = fields[1]","            self.state[\"utc_time\"] = f\"{t[0:2]}:{t[2:4]}:{t[4:6]}\"","","        # Fix quality","        try:","            fq = int(fields[6]) if fields[6] else 0","            self.state[\"fix_quality\"] = fq","            self.state[\"fix\"] = (fq > 0)","            if fq == 0:","                self.state[\"fix_type\"] = \"No Fix\"","            elif fq == 1:","                self.state[\"fix_type\"] = \"3D Fix (GPS)\"","            elif fq == 2:","                self.state[\"fix_type\"] = \"DGPS Fix\"","            else:","                self.state[\"fix_type\"] = f\"Fix Mode {fq}\"","        except ValueError:","            self.state[\"fix\"] = False","            self.state[\"fix_quality\"] = 0","","        # Satellites","        try:","            self.state[\"sats\"] = int(fields[7]) if fields[7] else 0","        except ValueError:","            pass","","        # Coordinates & Altitude (only update if fix valid or fields non-empty)","        if fields[2] and fields[3]:","            lat = parse_nmea_lat_lng(fields[2], fields[3])","            if lat is not None:","                self.state[\"lat\"] = lat","        if fields[4] and fields[5]:","            lng = parse_nmea_lat_lng(fields[4], fields[5])","            if lng is not None:","                self.state[\"lng\"] = lng","","        try:","            if fields[9]:","                self.state[\"altitude_m\"] = round(float(fields[9]), 1)","        except ValueError:","            pass"],"highlight":{"all":[244,248]}},"websocket_endpoint":{"file":"backend/websocket_handler.py","language":"python","name":"websocket_endpoint","start":26,"end":92,"lines":["async def websocket_endpoint(websocket: WebSocket):","    \"\"\"Handle a single WebSocket connection for its entire lifetime.\"\"\"","    await websocket.accept()","    connected_clients.add(websocket)","    client = websocket.client","    print(f\"[WS] Client connected: {client.host}:{client.port} | Total: {len(connected_clients)}\")","","    try:","        while True:","            raw = await websocket.receive_text()","","            # Parse the incoming message","            try:","                message = json.loads(raw)","            except json.JSONDecodeError:","                print(f\"[WS] Bad JSON from {client.host} \u2014 ignoring.\")","                continue","","            msg_type = message.get(\"type\")","            ts = message.get(\"ts\", 0)","            schema_ver = message.get(\"schema_version\")","","            if schema_ver != config.SCHEMA_VERSION:","                print(f\"[WS] \u26a0 SCHEMA MISMATCH: Client {client.host} sent version '{schema_ver}' (expected '{config.SCHEMA_VERSION}'). Forwarding as-is.\")","","            # \u2500\u2500 Route by message type \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500","            if msg_type == \"telemetry\":","                vehicle = message.get(\"vehicle\")","                source = message.get(\"source\")","                is_ev = isinstance(source, dict) and source.get(\"powertrain\") == \"ev\"","                # v2.2.0: a person drives this car from the Control Console and the gear","                # comes from the lever (0 = neutral even while rolling): never overwrite it.","                is_manual = isinstance(source, dict) and source.get(\"control\") == \"manual\"","                if is_manual and source.get(\"vehicle_id\"):","                    live_cars.setdefault(websocket, {})[str(source[\"vehicle_id\"])] = str(source.get(\"name\") or source[\"vehicle_id\"])","                if isinstance(vehicle, dict) and not is_ev and not is_manual:","                    # Automatically estimate/inject gear if missing or 0 while moving.","                    # v2.1.0: never for EVs (single-speed, no gearbox to estimate), and","                    # a null speed/rpm is \"unavailable\", so it cannot drive an estimate.","                    speed = vehicle.get(\"speed_kmh\")","                    rpm = vehicle.get(\"rpm\")","                    if not vehicle.get(\"gear\") and speed is not None and rpm is not None and speed >= 3:","                        vehicle[\"gear\"] = calculate_gear(rpm, speed)","                        raw = json.dumps(message)","","                save_telemetry(ts, message)","                await fan_out(raw, sender=websocket)","","            elif msg_type == \"demo_control\":","                # v2.1.0: presenter scenario from the fleet dashboard to the simulator.","                # Relayed to every other client, never saved -- it is not telemetry.","                print(f\"[WS] demo_control '{message.get('scenario')}' target={message.get('target')} -- relaying\")","                await fan_out(raw, sender=websocket)","","            else:","                print(f\"[WS] Unknown message type: '{msg_type}' \u2014 ignoring.\")","","    except WebSocketDisconnect:","        print(f\"[WS] Client disconnected: {client.host}:{client.port} | Total: {len(connected_clients) - 1}\")","    finally:","        connected_clients.discard(websocket)","        # v2.2.0: tell everyone else that this socket's live car(s) left the fleet.","        for vehicle_id, name in live_cars.pop(websocket, {}).items():","            await fan_out(json.dumps({","                \"type\": \"vehicle_left\", \"schema_version\": config.SCHEMA_VERSION,","                \"ts\": int(time.time() * 1000), \"vehicle_id\": vehicle_id, \"name\": name,","            }), sender=websocket)"],"highlight":{"all":[35,39,52,71,72]}},"fan_out":{"file":"backend/websocket_handler.py","language":"python","name":"fan_out","start":95,"end":114,"lines":["async def fan_out(raw_message: str, sender: WebSocket):","    \"\"\"Send a message to every connected client except the sender.\"\"\"","    dead_clients = set()","","    # Iterate over a snapshot: another client can connect or disconnect while","    # this coroutine is suspended in send_text(), which would otherwise raise","    # \"Set changed size during iteration\" and drop the sender's connection.","    for client in list(connected_clients):","        if client is sender:","            continue","        try:","            await client.send_text(raw_message)","        except Exception:","            # Client dropped without a clean disconnect","            dead_clients.add(client)","","    # Clean up any dead connections found during fan-out","    for dead in dead_clients:","        connected_clients.discard(dead)","        print(f\"[WS] Removed dead client during fan-out.\")"],"highlight":{"all":[102,106]}},"save_telemetry":{"file":"backend/database.py","language":"python","name":"save_telemetry","start":33,"end":41,"lines":["def save_telemetry(ts: int, payload: dict):","    \"\"\"Save a telemetry message to the database.\"\"\"","    conn = get_connection()","    conn.execute(","        \"INSERT INTO telemetry (ts, payload) VALUES (?, ?)\",","        (ts, json.dumps(payload))","    )","    conn.commit()","    conn.close()"],"highlight":{"all":[37,38]}},"init_db":{"file":"backend/database.py","language":"python","name":"init_db","start":16,"end":28,"lines":["def init_db():","    \"\"\"Create tables if they don't already exist. Called once on startup.\"\"\"","    conn = get_connection()","    conn.executescript(\"\"\"","        CREATE TABLE IF NOT EXISTS telemetry (","            id      INTEGER PRIMARY KEY AUTOINCREMENT,","            ts      INTEGER,","            payload TEXT","        );","    \"\"\")","    conn.commit()","    conn.close()","    print(\"[DB] Tables ready.\")"],"highlight":{"all":[20,22,23]}},"ft_connect":{"file":"demo/fleet-dashboard/js/app.js","language":"javascript","name":"FT.connect","start":240,"end":261,"lines":["  FT.connect = function () {","    const forced = new URLSearchParams(location.search).get(\"mode\") === \"standalone\";","    if (forced) return FT.startStandalone(\"requested in the URL\");","    let timer = setTimeout(() => {","      if (!opened) { try { ws && ws.close(); } catch (e) { /* ignore */ } FT.startStandalone(\"no backend answered within 4 s\"); }","    }, 4000);","    open();","    function open() {","      try { ws = new WebSocket(wsUrl()); } catch (e) { return; }","      ws.onopen = () => { opened = true; clearTimeout(timer); backoff = 1000; setMode(\"live\"); };","      ws.onmessage = (ev) => {","        let m; try { m = JSON.parse(ev.data); } catch (e) { return; }","        if (m && m.type === \"telemetry\") FT.ingest(m);","        else if (m && m.type === \"vehicle_left\" && m.vehicle_id && S.cars[m.vehicle_id]) FT.removeCar(String(m.vehicle_id), m.name);","      };","      ws.onclose = () => {","        if (S.mode === \"standalone\") return;","        if (opened) { setMode(\"reconnecting\"); setTimeout(open, backoff); backoff = Math.min(backoff * 2, 8000); }","      };","      ws.onerror = () => { /* onclose follows */ };","    }","  };"],"highlight":{"all":[250,251,252]}},"ft_ingest":{"file":"demo/fleet-dashboard/js/app.js","language":"javascript","name":"FT.ingest","start":39,"end":96,"lines":["  FT.ingest = function (msg) {","    if (!msg || msg.type !== \"telemetry\" || !msg.source || !msg.source.vehicle_id) return;","    const now = Date.now();","    const id = String(msg.source.vehicle_id);","    const car = carRecord(id);","    const isNew = !car.msg;","    car.prevRx = car.lastRx;","    car.msg = msg;","    car.lastRx = now;","    car.firstRx = car.firstRx || now;","    S.rx.push(now);","    car.rxTimes.push(now);","    while (S.rx.length && now - S.rx[0] > 5000) S.rx.shift();","    while (car.rxTimes.length && now - car.rxTimes[0] > 10000) car.rxTimes.shift();","","    // Re-check the CRC-8 of the packet in the browser (and trust the backend's flag too).","    let crcOk = msg.crc_valid !== false;","    const b32 = C.fromHex(msg.packet_hex);","    if (b32 && b32.length === 32) { car.crc32 = C.crc8(b32, 31) === b32[31]; crcOk = crcOk && car.crc32; }","    const b16 = C.fromHex(msg.tpms_hex);","    car.crc16 = null;","    if (b16 && b16.length === 16) { car.crc16 = C.crc8(b16, 15) === b16[15]; crcOk = crcOk && car.crc16 && msg.tpms_crc_valid !== false; }","    S.crc.total++; car.crcTotal++;","    if (crcOk) { S.crc.ok++; car.crcOk++; } else { raiseEvent(id, \"crc\", \"critical\", \"CRC-8 check failed: the packet was corrupted on the way\"); }","","    // Sequence gaps = packets that never arrived.","    const seq = msg.device && msg.device.seq;","    if (seq != null && car.lastSeq != null) {","      const gap = (seq - car.lastSeq - 1 + 256) % 256;","      if (gap > 0 && gap < 250) {","        car.gaps++; car.lost += gap;","        raiseEvent(id, \"seqgap\", \"warning\",","          `${gap} packet${gap > 1 ? \"s\" : \"\"} missing (seq ${car.lastSeq} then ${seq})`);","      }","    }","    if (seq != null) car.lastSeq = seq;","","    const v = msg.vehicle || {};","    const t = now / 1000;","    car.hist.push({ t, rpm: v.rpm, speed: v.speed_kmh });","    while (car.hist.length && t - car.hist[0].t > 125) car.hist.shift();","    if ((v.speed_kmh || 0) >= 3) car.lastMoveAt = now;","    const g = msg.gps || {};","    if (g.fix && g.lat != null && g.lng != null) {","      const last = car.longTrail[car.longTrail.length - 1];","      if (!last || last[0] !== g.lat || last[1] !== g.lng) {","        car.longTrail.push([g.lat, g.lng]);","        if (car.longTrail.length > 180) car.longTrail.shift();","      }","    }","","    // Data came back: staleness clears.","    clearAlert(id, \"stale\");","    clearAlert(id, \"offline\");","    evaluate(id, msg);","    if (isNew && FT.isLiveCar(msg)) FT.postInfo(id, `Live car joined: ${msg.source.name}, driven from the Control Console`);","    emit(isNew ? \"newcar\" : \"telemetry\", car);","  };"],"highlight":{"all":[46,57,93,95]}},"set_tile":{"file":"demo/fleet-dashboard/js/car.js","language":"javascript","name":"setTile","start":359,"end":378,"lines":["  function setTile(node, value, state, msg, digits, unit, opts) {","    const valEl = node.querySelector(\".tile-value\");","    const provEl = node.querySelector(\".prov\");","    const isNull = value == null;","    node.classList.toggle(\"is-null\", isNull);","    let html;","    if (isNull) html = FT.esc(FT.nullText(state, msg));","    else if (opts && opts.text) html = FT.esc(opts.text);","    else html = FT.esc(digits == null ? String(value) : Number(value).toFixed(digits)) + (unit ? `<small>${unit}</small>` : \"\");","    if (opts && opts.extra) html += opts.extra;","    if (valEl.innerHTML !== html) valEl.innerHTML = html;","    const pt = FT.provText(state, msg);","    if (provEl.dataset.p !== state || provEl.textContent !== pt) { provEl.dataset.p = state; provEl.textContent = pt; provEl.title = pt; }","    node.classList.toggle(\"is-alert\", !!(opts && opts.alert));","    // status never by colour alone: an alerted tile also carries the critical icon","    const lbl = node.querySelector(\".tile-label\");","    const has = lbl.querySelector(\".icon\");","    if (opts && opts.alert && !has) lbl.insertAdjacentHTML(\"afterbegin\", FT.icon(\"i-crit\"));","    else if (!(opts && opts.alert) && has) has.remove();","  }"],"highlight":{"all":[365,367,370]}}};
